diff --git a/packages/workflow/src/workflow-expression.ts b/packages/workflow/src/workflow-expression.ts
index 0c15b632b..b0f9a9fda 100644
--- a/packages/workflow/src/workflow-expression.ts
+++ b/packages/workflow/src/workflow-expression.ts
@@ -1,6 +1,7 @@
 import { Expression } from './expression';
 import { isExpression } from './expressions/expression-helpers';
 import type {
+	IDataObject,
 	IExecuteData,
 	INode,
 	INodeExecutionData,
@@ -237,6 +238,28 @@ export class WorkflowExpression {
 		const connectionInputData: INodeExecutionData[] = [];
 		const runData = createEmptyRunExecutionData();

+		// Values in `selfData` (e.g. credential data exposed as `$self`) may themselves be
+		// in expression mode. Resolve them first so `$self.x` returns the resolved value
+		// instead of the raw `={{ ... }}` string.
+		const resolvedSelfData: IDataObject = {};
+		for (const [key, value] of Object.entries(selfData as IDataObject)) {
+			resolvedSelfData[key] = isExpression(value)
+				? this.resolveSimpleParameterValue(
+						value,
+						{},
+						runData,
+						runIndex,
+						itemIndex,
+						node.name,
+						connectionInputData,
+						mode,
+						additionalKeys,
+						executeData,
+					)
+				: value;
+		}
+		selfData = resolvedSelfData;
+
 		const returnData = this.getParameterValue(
 			parameterValue,
 			runData,
diff --git a/packages/workflow/test/workflow-expression.test.ts b/packages/workflow/test/workflow-expression.test.ts
index 1a27cf63d..8d0279a8a 100644
--- a/packages/workflow/test/workflow-expression.test.ts
+++ b/packages/workflow/test/workflow-expression.test.ts
@@ -45,4 +45,59 @@ describe('WorkflowExpression', () => {
 			expect(result).toEqual({ key: 'title|display', type: 'display' });
 		});
 	});
+
+	describe('getComplexParameterValue()', () => {
+		const nodeTypes = Helpers.NodeTypes();
+		const node = {
+			name: 'node',
+			typeVersion: 1,
+			type: 'test.set',
+			id: 'uuid-1234',
+			position: [0, 0] as [number, number],
+			parameters: {},
+		};
+		const workflow = new Workflow({
+			id: '1',
+			nodes: [node],
+			connections: {},
+			active: false,
+			nodeTypes,
+		});
+		const expression = workflow.expression;
+
+		beforeAll(async () => {
+			await expression.acquireIsolate();
+		});
+		afterAll(async () => {
+			await expression.releaseIsolate();
+		});
+
+		it('should resolve plain $self values in a credential template', () => {
+			const result = expression.getComplexParameterValue(
+				node,
+				{ headers: { Authorization: '=Bearer {{$self.token}}' } },
+				'manual',
+				{},
+				undefined,
+				undefined,
+				{ token: 'abc123' },
+			);
+
+			expect(result).toEqual({ headers: { Authorization: 'Bearer abc123' } });
+		});
+
+		it('should resolve expression-mode $self values in a credential template', () => {
+			const result = expression.getComplexParameterValue(
+				node,
+				{ headers: { Authorization: '=Bearer {{$self.token}}' } },
+				'manual',
+				{},
+				undefined,
+				undefined,
+				{ token: "={{ 'abc' + '123' }}" },
+			);
+
+			expect(result).toEqual({ headers: { Authorization: 'Bearer abc123' } });
+		});
+	});
 });
